<?php require_once 'bootstrap.php';$u=require_login();vault_reserve_sync();$reserve=vault_pool_balance('RESERVE');$community=vault_pool_balance('COMMUNITY');$rules=db()->query('SELECT * FROM community_drop_rules WHERE active=1 ORDER BY threshold_drx')->fetchAll();$next=null;foreach($rules as $r)if($reserve<(float)$r['threshold_drx']){$next=$r;break;}$pageTitle='DRX Community Vault';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Community Economy</span><h1>DRX Community Vault</h1><p>I reward non reclamati restano una riserva dovuta agli utenti: non vengono spesi due volte. La riserva può attivare soglie Community Drop, finanziate dal pool comunitario separato.</p></div></section><section class="metric-grid"><div class="metric"><b><?=number_format($reserve,0,',','.')?></b><span>DRX Reserve liability</span></div><div class="metric"><b><?=number_format($community,0,',','.')?></b><span>DRX Community Pool</span></div><?php if($next):?><div class="metric"><b><?=number_format((int)$next['threshold_drx'],0,',','.')?></b><span>Prossima soglia</span></div><div class="metric"><b><?=number_format(max(0,(float)$next['threshold_drx']-$reserve),0,',','.')?></b><span>Mancano</span></div><?php endif;?></section><section class="card"><h2>Regole drop</h2><?php foreach($rules as $r):?><div class="leader-row"><b>◆</b><span><?=h($r['label'])?></span><em><?=number_format((int)$r['threshold_drx'],0,',','.')?> DRX</em></div><?php endforeach;?></section><section class="card"><p><b>Regola contabile:</b> RESERVE ≠ COMMUNITY. Un DRX ancora dovuto a un utente non può finanziare contemporaneamente il premio di un altro.</p></section><?php require '_footer.php';?>